INSERT INTO "proofs" ("id","academy_id","created_by","title","grade","chapter","difficulty","description","description_image","is_shared","share_count","created_at","updated_at","theorem_statement","subject","source_path") VALUES('prf_m1_vertical','acad-1','system','맞꼭지각의 크기는 같다','중1','평면도형',1,'두 직선이 한 점에서 만날 때 마주보는 두 각의 크기는 같음을 평각의 성질로 증명',NULL,1,0,'2026-04-15 02:52:59',NULL,'두 직선이 교차할 때 ∠1 = ∠3 (맞꼭지각)','geometry','middle/05_중1_기하/vertical_angles.typ');
INSERT INTO "proofs" ("id","academy_id","created_by","title","grade","chapter","difficulty","description","description_image","is_shared","share_count","created_at","updated_at","theorem_statement","subject","source_path") VALUES('prf_m1_exp_mul','acad-1','system','지수법칙 ① 곱셈','중1','문자와 식',2,'거듭제곱의 정의로부터 a의 m번 곱과 n번 곱을 이어 붙이면 (m+n)번 곱이 된다',NULL,1,0,'2026-04-15 02:52:59',NULL,'양의 정수 m, n에 대하여 aᵐ × aⁿ = aᵐ⁺ⁿ','algebra','middle/02_중1_문자와식/이시은_exp_rule1_곱셈.typ');
INSERT INTO "proofs" ("id","academy_id","created_by","title","grade","chapter","difficulty","description","description_image","is_shared","share_count","created_at","updated_at","theorem_statement","subject","source_path") VALUES('prf_m1_eq_props','acad-1','system','등식의 성질 (이항 원리)','중1','방정식',1,'등식의 양변에 같은 수를 더해도(빼도/곱해도/나눠도) 등식이 성립한다',NULL,1,0,'2026-04-15 02:52:59',NULL,'a=b이면 a+c=b+c, a−c=b−c, ac=bc, a/c=b/c (c≠0)','algebra','middle/03_중1_방정식/equality_properties.typ');
INSERT INTO "proofs" ("id","academy_id","created_by","title","grade","chapter","difficulty","description","description_image","is_shared","share_count","created_at","updated_at","theorem_statement","subject","source_path") VALUES('prf_m1_prime_fact','acad-1','system','소인수분해의 유일성 (개요)','중1','수와 연산',3,'1보다 큰 자연수는 소수들의 곱으로 유일하게 표현됨(순서 제외)을 예시로 이해',NULL,1,0,'2026-04-15 02:52:59',NULL,'1보다 큰 자연수 n은 n = p₁ × p₂ × ... × pₖ (pᵢ는 소수)로 유일하게 표현된다.','number','middle/01_중1_수와연산/prime_factorization.typ');
