INSERT INTO "proof_steps" ("id","proof_id","step_order","content","content_image","blanks_json","hint") VALUES('step_tas_4','prf_m1_tri_angle_sum',4,'엇각 대입: ∠ABC + ∠BAC + ∠BCA = 180°. 증명 완료.',NULL,'[{"placeholder":"평행","answer":"평행"},{"placeholder":"엇각","answer":"엇각"},{"placeholder":"180","answer":"180"}]',NULL);
