INSERT INTO "proof_steps" ("id","proof_id","step_order","content","content_image","blanks_json","hint") VALUES('step_pf_3','prf_m1_prime_fact',3,'15 = 3 × 5이므로 60 = 2 × 2 × 3 × 5.',NULL,NULL,NULL);
