INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_tas_2','prf_m1_tri_angle_sum',2,'blank','빈칸을 채워 증명을 완성하시오.',NULL);
INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_tas_3','prf_m1_tri_angle_sum',3,'blank_paper','꼭짓점 A를 지나고 BC에 평행한 직선을 이용하여 ∠A+∠B+∠C=180°임을 증명하시오.','보조선 ℓ∥BC를 A에 긋고, 엇각으로 ∠B=∠DAB, ∠C=∠EAC, 평각으로 ∠DAB+∠BAC+∠CAE=180°, 대입하면 ∠A+∠B+∠C=180°.');
INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_va_1','prf_m1_vertical',1,'order','단계 A~C를 순서대로 배열하시오.','B,A,C');
INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_va_2','prf_m1_vertical',2,'blank','빈칸을 채우시오.',NULL);
INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_va_3','prf_m1_vertical',3,'blank_paper','두 직선의 교점에서 생기는 맞꼭지각 ∠1=∠3을 증명하시오.','∠1+∠2=180°(평각), ∠2+∠3=180°(평각). 두 식에서 ∠1=180°−∠2=∠3.');
INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_em_1','prf_m1_exp_mul',1,'order','단계 A~C를 순서대로 배열하시오.','A,B,C');
INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_em_2','prf_m1_exp_mul',2,'blank','빈칸을 채우시오.',NULL);
INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_em_3','prf_m1_exp_mul',3,'blank_paper','aᵐ × aⁿ = aᵐ⁺ⁿ을 거듭제곱의 정의로부터 증명하시오.','aᵐ×aⁿ = (a×...×a, m개)×(a×...×a, n개) = a×...×a, (m+n)개 = aᵐ⁺ⁿ.');
