INSERT INTO "proof_phases" ("id","proof_id","phase_no","phase_type","prompt","model_answer") VALUES('ph_ep_3','prf_m1_eq_props',3,'blank_paper','등식의 성질을 이용해 2x+5=13을 풀고 각 단계의 근거를 쓰시오.','2x+5=13 → (양변에서 5를 뺌) 2x=8 → (양변을 2로 나눔) x=4.');
