INSERT INTO "proof_figures" ("id","proof_id","phase_id","svg_content","coords_json","verify_meta_json","verify_result_json","highlight_keys","alt_text","review_status","created_at") VALUES('fig_tas_main','prf_m1_tri_angle_sum',NULL,replace('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 260" width="300" height="260">\n    <style>\n      .tri{fill:none;stroke:#1e40af;stroke-width:2.2}\n      .aux{stroke:#9ca3af;stroke-width:1.5;stroke-dasharray:5 3}\n      .arc{fill:none;stroke-width:1.6}\n      .vlabel{font:bold 14px sans-serif;fill:#111}\n      .alabel{font:italic 11px sans-serif}\n      .aux-label{font:11px sans-serif;fill:#6b7280}\n    </style>\n    <line id="line_l" class="aux" x1="20" y1="40" x2="280" y2="40"/>\n    <text class="aux-label" x="5" y="44">ℓ</text>\n    <polygon id="triangle_abc" class="tri" points="150,40 40,220 260,220"/>\n    <line id="line_ad" class="aux" x1="40" y1="40" x2="150" y2="40" stroke="#6b7280" stroke-dasharray="0"/>\n    <line id="line_ae" class="aux" x1="150" y1="40" x2="260" y2="40" stroke="#6b7280" stroke-dasharray="0"/>\n    <path id="arc_DAB" class="arc" stroke="#dc2626" d="M 120,40 A 30,30 0 0,0 135,56"/>\n    <text class="alabel" fill="#dc2626" x="100" y="58">∠DAB</text>\n    <path id="arc_BAC" class="arc" stroke="#059669" d="M 135,56 A 24,24 0 0,0 166,56"/>\n    <text class="alabel" fill="#059669" x="142" y="76">∠A</text>\n    <path id="arc_CAE" class="arc" stroke="#d97706" d="M 166,56 A 30,30 0 0,0 180,40"/>\n    <text class="alabel" fill="#d97706" x="175" y="58">∠CAE</text>\n    <path id="arc_B" class="arc" stroke="#dc2626" d="M 56,214 A 20,20 0 0,1 72,202"/>\n    <text class="alabel" fill="#dc2626" x="60" y="200">∠B</text>\n    <path id="arc_C" class="arc" stroke="#d97706" d="M 244,214 A 20,20 0 0,0 228,202"/>\n    <text class="alabel" fill="#d97706" x="222" y="200">∠C</text>\n    <circle cx="150" cy="40" r="3" fill="#111"/>\n    <circle cx="40" cy="220" r="3" fill="#111"/>\n    <circle cx="260" cy="220" r="3" fill="#111"/>\n    <circle cx="40" cy="40" r="2.5" fill="#6b7280"/>\n    <circle cx="260" cy="40" r="2.5" fill="#6b7280"/>\n    <text class="vlabel" x="145" y="30">A</text>\n    <text class="vlabel" x="26" y="236">B</text>\n    <text class="vlabel" x="265" y="236">C</text>\n    <text class="aux-label" x="28" y="34">D</text>\n    <text class="aux-label" x="265" y="34">E</text>\n  </svg>','\n',char(10)),'{"A":[150,40],"B":[40,220],"C":[260,220],"D":[40,40],"E":[260,40]}',replace('{"assertions":[\n    {"type":"collinear","points":["D","A","E"]},\n    {"type":"parallel","line1":["D","E"],"line2":["B","C"]},\n    {"type":"triangle_angle_sum","vertices":["A","B","C"],"expected":180},\n    {"type":"alternate_angles","a1":["B","-","ABC"],"a2":["DAB"]},\n    {"type":"alternate_angles","a1":["C","-","ACB"],"a2":["EAC"]},\n    {"type":"straight_at","vertex":"A","angles":["DAB","BAC","CAE"],"expected":180}\n  ]}','\n',char(10)),replace('{"status":"PASS","checks":[\n    {"name":"D,A,E 공선","result":"PASS","detail":"∠DAE=180.000°"},\n    {"name":"ℓ ∥ BC","result":"PASS","detail":"slope(DE)=0.000, slope(BC)=0.000"},\n    {"name":"∠A+∠B+∠C=180°","result":"PASS","detail":"62.86+58.57+58.57=180.000"},\n    {"name":"∠B=∠DAB","result":"PASS","detail":"58.570=58.570"},\n    {"name":"∠C=∠EAC","result":"PASS","detail":"58.570=58.570"},\n    {"name":"A에서 평각 180°","result":"PASS","detail":"합=180.000°"}\n  ],"verified_at":"2026-04-15"}','\n',char(10)),'triangle_abc,line_l,arc_DAB,arc_BAC,arc_CAE,arc_B,arc_C','삼각형 ABC와 꼭짓점 A를 지나고 BC에 평행한 보조선 ℓ. ℓ 위의 두 점 D(왼쪽), E(오른쪽). 엇각 ∠B=∠DAB, ∠C=∠EAC, 그리고 A에서의 평각 ∠DAB+∠BAC+∠CAE=180° 표시됨.','approved','2026-04-15 03:03:43');
INSERT INTO "paper_handouts" ("id","academy_id","title","exam_type","subject","school","grade","exam_year","semester","file_key","file_name","file_size","content_type","memo","created_by","created_at","updated_at") VALUES('206313ed-16a1-414f-8345-e8004b8d1042','acad-1','수직선위에 무리수 나타내기','performance','수학','고산중','중3',2026,1,NULL,NULL,NULL,NULL,'정지효','user-57ppx9v61','2026-04-16 06:29:40','2026-04-16 06:29:40');
INSERT INTO "paper_handouts" ("id","academy_id","title","exam_type","subject","school","grade","exam_year","semester","file_key","file_name","file_size","content_type","memo","created_by","created_at","updated_at") VALUES('7264cdc4-6bc3-411f-9bc6-9816448ca912','acad-1','2026년도 시지고 중간고사 범위','midterm','수학','시지고','고2',2026,1,'exam-papers/acad-1/1776350524559-1aacd2c8-0c92-4c42-b21d-0fc19ed783b6.jpg','KakaoTalk_20260416_233519127.jpg',388455,'image/jpeg',replace('1. 확률과 통계\n시험 범위:\n\nI. 경우의 수\n\nII. 확률: 01. 조건부확률까지\n\n교과서: p.10 ~ p.62, p.67 ~ p.73 중 시험 범위에 해당되는 모든 문제\n\n기타: 수업 시간에 나눠준 학습지 전부\n\n문항 수: 객관식 15문항 내외, 서술형 6문항 내외\n\n2. 대수 (Algebra)\n시험 범위:\n\nI. 지수와 로그\n\nII. 지수함수와 로그함수\n\nIII. 삼각함수\n\n일반각과 호도법\n\n삼각함수의 뜻\n\n삼각함수의 그래프\n\n교과서: 처음 ~ p.89의 모든 내용, p.98 ~ p.100 중 해당 내용\n\n기타: 수업 시간에 나눠준 학습지 전부\n\n문항 수: 객관식 15문항 내외, 단답형 1문항(5점), 서술형 5문항 내외','\n',char(10)),'user-57ppx9v61','2026-04-16 14:42:05','2026-04-16 14:42:05');
INSERT INTO "paper_handouts" ("id","academy_id","title","exam_type","subject","school","grade","exam_year","semester","file_key","file_name","file_size","content_type","memo","created_by","created_at","updated_at") VALUES('477fbb18-8dab-41c6-8c4d-d7f69981d64b','acad-1','2026년도 고산중 중간고사 범위','midterm','수학','고산중','중3',2026,1,'exam-papers/acad-1/1776350796681-1848284b-21f0-4576-9f34-340a05403d6e.jpg','KakaoTalk_20260415_180029068.jpg',2366841,'image/jpeg',replace('교과서: p.11 ~ p.83 내용 및 문제\n\n교과서 추가: p.107 ~ p.109에서 내용 시험 범위 문제만 해당\n\n기타: 교과서 범위에 해당하는 학습지','\n',char(10)),'user-57ppx9v61','2026-04-16 14:46:38','2026-04-16 14:46:38');
INSERT INTO "paper_handouts" ("id","academy_id","title","exam_type","subject","school","grade","exam_year","semester","file_key","file_name","file_size","content_type","memo","created_by","created_at","updated_at") VALUES('1118a6d8-94cd-4de5-9c48-4a5630d8a855','acad-1','2026년도 노변중 중간고사','midterm','수학','노변중','중2',2026,1,'exam-papers/acad-1/1776350884649-66c96b65-52cd-49d6-9ba8-cfa1b8a44389.png','KakaoTalk_20260414_161200237.png',206351,'image/png',replace('- 교과서: 처음 ~ p.71\n\n\n- 교과서 추가: p.90 ~ p.91 (대단원 평가 중 해당 범위 문제)\n\n\n- 교과서 추가: p.262 ~ p.264\n\n\n- 기타: 해당 범위 학습지','\n',char(10)),'user-57ppx9v61','2026-04-16 14:48:06','2026-04-16 14:48:06');
INSERT INTO "paper_handouts" ("id","academy_id","title","exam_type","subject","school","grade","exam_year","semester","file_key","file_name","file_size","content_type","memo","created_by","created_at","updated_at") VALUES('47b44e45-bc70-4317-b30d-49b1650a8927','acad-1','2026년도 삼육고 중간고사','midterm','수학','삼육고','고1',2026,1,NULL,NULL,NULL,NULL,replace('범위: 처음 ~ Ⅱ. 방정식과 부등식 - 2. 복소수와 이차방정식 - 02. 이차방정식과 이차함수\n\n페이지: ~ p.75까지\n\n주요 내용: 다항식의 연산부터 복소수, 그리고 이차함수의 그래프와 그 관계까지 포함되는 범위입니다.','\n',char(10)),'user-57ppx9v61','2026-04-16 14:51:38','2026-04-16 14:51:38');
