INSERT INTO "grades" ("id","student_id","exam_id","score","comments","graded_at","graded_by","created_at","year_month") VALUES('grade-32d15c82','student-8dbc66f9','exam-5a571ba8',0,'기말대비 진도 진행중입니다. 지권의 변화 단원부터 진도 나가는 중이고 이번 단원은 암기량이 다소 있기 때문에 꼼곰하게 숙지하고 여러 유형의 문제들을 다루어볼 수 있도록 수업 진행할 예정입니다.','2026-05-19T07:37:15.055Z','user-nam01hyun','2026-05-19T07:18:33.058Z','2026-04');
