INSERT INTO "grades" ("id","student_id","exam_id","score","comments","graded_at","graded_by","created_at","year_month") VALUES('grade-a9b7fabd','student-tdx0c9nmo','exam-5a571ba8',95,'새 교재 진도도 마무리가 되고 있습니다. 교재 마무리 후 좀 더 다양한 과학적 내용들을 다루어볼 수 있도록 수업 구상중입니다.','2026-05-19T07:39:19.149Z','user-nam01hyun','2026-05-19T07:38:20.548Z','2026-04');
