INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_3e2fd7c851','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','endure','1. 견디다, 참다 2. 지속되다, 오래가다',NULL);
