INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_c75525a6b6','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','describe','묘사하다, 설명하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_aa8d050c59','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','prescribe','1. (약을) 처방하다 2. 규정하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_3d59f7d412','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','compare','1. 비교하다 2. 비유하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_5de2584eba','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','divide','나누다, 갈라지다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_841510b85e','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','classify','분류하다, 구분하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_3b0b7f7fcb','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','relate','관련시키다, 관련이 있다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_c424c43ca5','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','violate','1. 위반하다 2. 침해하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_3eb8d6c071','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','forbid','금지하다; 못 하게 하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_d1856696a7','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','control','1. 통제하다 2. 지배하다 3. 조절하다; 1. 통제 2. 지배',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_c74eeade50','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','commit','1. (범죄 등을) 저지르다 2. 약속하다 3. 전념하다, 헌신하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_e74aee76a6','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','release','1. 석방하다 2. 발매하다, 개봉하다 3. 방출하다, 내뿜다; 1. 석방 2. 발매, 개봉 3. 방출',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_6fd70c8f92','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','focus','1. 집중하다, 집중시키다 2. 초점을 맞추다; 1. 집중 2. 초점',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_d4f3eba797','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','concentrate','1. 집중하다, 집중시키다 2. 농축하다; 농축물',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_740f53c762','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','drip','(액체가) 뚝뚝 떨어지다; (액체를) 뚝뚝 떨어뜨리다; (액체) 방울',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_3e6b1e5a58','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','determine','1. 결정하다 2. 결심하다 3. 알아내다, 밝히다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_5bd24cef82','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','conclude','1. 결론을 내리다 2. 끝내다, 끝나다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_c2b26348e4','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','fit','1. (모양, 크기가) 맞다 2. 어울리다, 적합하다; 1. 어울리는, 적합한 2. (운동으로 몸이) 건강한',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_f46d8d2003','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','belong','(~의) 것이다, 소유이다; (~에) 속하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_53300c203e','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','occur','1. 발생하다, 일어나다 2. (생각이) 떠오르다 3. (~에) 존재하다',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_d33f7a1276','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','blossom','1. 꽃이 피다 2. (얼굴, 형편이) 피다, 좋아지다; (과일나무의) 꽃',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_492783db3d','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','notice','1. 알아차리다 2. 주목하다 3. 통지하다; 1. 주의, 주목 2. 통지(서); 게시(물)',NULL);
INSERT INTO "vocab_textbook_words" ("id","textbook_id","unit","english","korean","sentence") VALUES('vtw_bc12979027','vtb_549e9ae652','Unit 01. 약방의 감초, 기본 동사 1','inform','알리다, 통지하다',NULL);
