INSERT INTO "vocab_catalog_words" ("id","catalog_id","english","korean","pos","rank","tier","example") VALUES('vtw_37761853ec','vtb_981fee88d8','still',replace('[부] 1. 아직 2. 그럼에도 불구하고 3. ((비교급 강조)) 훨씬\n[형] 가만히 있는, 정지한','\n',char(10)),NULL,994,3,NULL);
