INSERT INTO "vocab_catalog_words" ("id","catalog_id","english","korean","pos","rank","tier","example") VALUES('vtw_8360dac05b','vtb_981fee88d8','thus','[부] 1. 이렇게, 이와 같이 2. 따라서, 그러므로',NULL,997,3,NULL);
