INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-001','med-basic-ch01',1,'객관식','단어 요소 정의','하','단어의 앞에 붙어 단어의 뜻을 확대하거나 강조하는 단어 요소는?','{"choices": ["접미사 (suffix)", "접두사 (prefix)", "어근 (word root)", "결합 모음 (combining vowel)"]}','"B"','접두사는 단어의 앞에 붙는 단어 요소로, 단어의 뜻을 확대·강조한다. 예: con-struction의 ''con-''.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-002','med-basic-ch01',2,'객관식','단어 요소 정의','하','용어의 일차적인(근본적인) 의미를 제공하며, 다른 단어 요소들이 부착되는 단어의 핵심 부분은?','{"choices": ["접두사", "접미사", "어근", "결합형"]}','"C"','어근(word root)은 용어의 핵심으로 일차적 의미를 제공한다. construction의 ''struct''(만들다)가 어근의 예.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-003','med-basic-ch01',3,'객관식','결합 모음','중','결합 모음(combining vowel)에 대한 설명으로 옳은 것은?','{"choices": ["어근의 의미를 변화시킨다", "접두사 끝에 항상 붙는다", "대부분 ''o''이며, 발음을 도와준다", "모음으로 시작하는 접미사 앞에서 반드시 사용한다"]}','"C"','결합 모음은 어근의 뜻을 바꾸지 않고 발음을 돕는 역할이며, 가장 일반적인 결합 모음은 ''o''이다 (i, e도 일부 사용).',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-004','med-basic-ch01',4,'객관식','조합어/비조합어','중','다음 중 비조합어(nonconstructed term)에 해당하는 것은?','{"choices": ["cardiology", "eustachian tube", "gastroenteritis", "encephalitis"]}','"B"','eustachian tube는 사람 이름(Bartolommeo Eustachio)에서 유래한 비조합어. 단어 요소로 분해되지 않으며 외워야 한다.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-005','med-basic-ch01',5,'용어분해','단어 분해','중','다음 용어를 단어 요소로 분리하시오: cardiology','{"parts": [{"role": "r", "value": "cardi", "label_ko": "어근"}, {"role": "cv", "value": "o", "label_ko": "결합모음"}, {"role": "s", "value": "-logy", "label_ko": "접미사"}]}','"cardi/o/logy"','cardi(심장) + o(결합모음) + -logy(학문/과학) → ''심장을 연구하는 학문''.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-006','med-basic-ch01',6,'용어분해','단어 분해','중','다음 용어를 단어 요소로 분리하시오: gastroenteritis','{"parts": [{"role": "r", "value": "gastr", "label_ko": "어근1"}, {"role": "cv", "value": "o", "label_ko": "결합모음"}, {"role": "r", "value": "enter", "label_ko": "어근2"}, {"role": "s", "value": "-itis", "label_ko": "접미사"}]}','"gastr/o/enter/itis"','gastr(위장) + o + enter(소장) + -itis(염증) → ''위장과 소장의 염증''.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-007','med-basic-ch01',7,'용어분해','단어 분해','중','다음 용어를 단어 요소로 분리하시오: microscopic','{"parts": [{"role": "p", "value": "micro-", "label_ko": "접두사"}, {"role": "r", "value": "scop", "label_ko": "어근"}, {"role": "s", "value": "-ic", "label_ko": "접미사"}]}','"micro/scop/ic"','micro-(작은) + scop(관찰 도구) + -ic(형용사 어미) → ''현미경의''.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-008','med-basic-ch01',8,'용어분해','단어 분해','상','다음 용어를 단어 요소로 분리하시오: musculoskeletal','{"parts": [{"role": "r", "value": "muscul", "label_ko": "어근1"}, {"role": "cv", "value": "o", "label_ko": "결합모음"}, {"role": "r", "value": "skelet", "label_ko": "어근2"}, {"role": "s", "value": "-al", "label_ko": "접미사"}]}','"muscul/o/skelet/al"','muscul(근육) + o + skelet(골격) + -al(형용사 어미) → ''근골격의''. 두 어근이 결합할 때 결합 모음 o가 필요하다.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-009','med-basic-ch01',9,'단답형','용어 만들기','하','''뇌염''에 해당하는 의학용어를 단어 요소(encephal/o + -itis)로 조합하시오.','{}','"encephalitis"','encephal(뇌) + -itis(염증). 접미사가 모음(i)으로 시작하므로 결합 모음을 붙이지 않는다.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-010','med-basic-ch01',10,'단답형','용어 만들기','중','''유방의 외과적 제거(절제)''에 해당하는 의학용어는?','{}','"mastectomy"','mast(유방) + -ectomy(외과적 제거). mamm/o + -ectomy → mammectomy도 가능하지만 표준 임상 용어는 mastectomy.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-011','med-basic-ch01',11,'단답형','용어 만들기','중','''코의 외과적 복원(성형)''에 해당하는 의학용어는?','{}','"rhinoplasty"','rhin(코) + o(결합모음) + -plasty(외과적 복원/성형). 접미사가 자음 p로 시작하므로 결합 모음 o가 필요.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-012','med-basic-ch01',12,'단답형','용어 만들기','중','''유방의 X-선 영상''에 해당하는 의학용어는?','{}','"mammogram"','mamm(유방) + o + -gram(기록/이미지).',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-013','med-basic-ch01',13,'단답형','용어 만들기','상','''자궁의 외과적 제거''에 해당하는 의학용어는?','{}','"hysterectomy"','hyster(자궁) + -ectomy(외과적 제거). -ectomy의 e(모음) 앞이라 결합 모음 생략.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-014','med-basic-ch01',14,'매칭','결합형 의미','하','다음 결합형과 의미를 짝지으시오.','{"items": {"1": "cardi/o", "2": "gastr/o", "3": "encephal/o", "4": "oste/o", "5": "dermat/o"}, "options": {"a": "뇌", "b": "심장", "c": "피부", "d": "위장", "e": "뼈"}}','{"1": "b", "2": "d", "3": "a", "4": "e", "5": "c"}',NULL,NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-015','med-basic-ch01',15,'매칭','접미사 의미','중','다음 접미사와 의미를 짝지으시오.','{"items": {"1": "-itis", "2": "-ectomy", "3": "-logy", "4": "-plasty", "5": "-gram"}, "options": {"a": "외과적인 복원(성형)", "b": "기록, 이미지", "c": "염증", "d": "연구, 과학", "e": "외과적인 제거"}}','{"1": "c", "2": "e", "3": "d", "4": "a", "5": "b"}',NULL,NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-016','med-basic-ch01',16,'매칭','접두사 의미','중','다음 접두사와 의미를 짝지으시오.','{"items": {"1": "anti-", "2": "brady-", "3": "endo-", "4": "epi-", "5": "neo-", "6": "pre-"}, "options": {"a": "위쪽의, 꼭대기에", "b": "안(내부)", "c": "전의", "d": "반대", "e": "느린", "f": "새로운"}}','{"1": "d", "2": "e", "3": "b", "4": "a", "5": "f", "6": "c"}',NULL,NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-017','med-basic-ch01',17,'객관식','복수형 규칙','중','다음 중 복수형 규칙이 잘못 짝지어진 것은?','{"choices": ["vertebra → vertebrae", "diagnosis → diagnoses", "gastritis → gastritises", "myocardium → myocardia"]}','"C"','용어가 -itis로 끝나면 복수형은 -itides. 따라서 gastritis → gastritides.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-018','med-basic-ch01',18,'단답형','복수형','중','다음 단어의 복수형을 쓰시오: ganglion','{}','"ganglia"','용어가 -on 또는 -um으로 끝나면 -on/-um을 떼고 -a를 붙인다. ganglion → ganglia.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-019','med-basic-ch01',19,'빈칸','단어 구성 규칙','중','어근에 모음으로 시작하는 접미사를 붙일 때는 결합 모음을 ( ① ). 어근에 자음으로 시작하는 접미사를 붙일 때는 결합 모음을 ( ② ).','{}','{"①": "붙이지 않는다(생략한다)", "②": "붙인다(사용한다)"}','예: cardi + -itis → carditis (모음 시작, 결합모음 X) / cardi + o + -logy → cardiology (자음 시작, 결합모음 O).',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-020','med-basic-ch01',20,'OX','단어 구성 규칙','하','접두사는 다른 단어 요소와 조합하기 위해 결합 모음을 반드시 필요로 한다.','{}','"X"','접두사는 모음 없이 어근에 직접 붙는다. (예: epi-derm-is, micro-scop-ic)',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-021','med-basic-ch01',21,'객관식','단어 분석 절차','중','의학용어를 분석할 때 단어 요소를 확인하는 올바른 순서는?','{"choices": ["어근 → 접두사 → 접미사", "접두사 → 어근 → 접미사", "접미사 → 어근 → 접두사", "접미사 → 접두사 → 어근"]}','"C"','단어 요소를 분리한 후 접미사를 먼저 확인하고, 다음으로 어근, 마지막에 접두사를 확인한다.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-022','med-basic-ch01',22,'용어분해','단어 분해','상','다음 용어를 단어 요소로 분리하시오: cardiopulmonary','{"parts": [{"role": "r", "value": "cardi", "label_ko": "어근1"}, {"role": "cv", "value": "o", "label_ko": "결합모음"}, {"role": "r", "value": "pulmon", "label_ko": "어근2"}, {"role": "s", "value": "-ary", "label_ko": "접미사"}]}','"cardi/o/pulmon/ary"','cardi(심장) + o + pulmon(허파) + -ary(형용사 어미) → ''심장허파의''.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-023','med-basic-ch01',23,'용어분해','단어 분해','중','다음 용어를 단어 요소로 분리하시오: epidermis','{"parts": [{"role": "p", "value": "epi-", "label_ko": "접두사"}, {"role": "r", "value": "derm", "label_ko": "어근"}, {"role": "s", "value": "-is", "label_ko": "접미사"}]}','"epi/derm/is"','epi-(위쪽의/꼭대기) + derm(피부) + -is → ''피부의 제일 위층(표피)''.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-024','med-basic-ch01',24,'객관식','어원','중','그리스어 ''salpinx(트럼펫)''에서 유래된 의학용어가 아닌 것은?','{"choices": ["salpingitis", "salpingoplasty", "salpingo-oophorectomy", "cholelithiasis"]}','"D"','cholelithiasis는 lith(돌, 그리스어 lithos)에서 유래한 담석증. 나머지는 모두 salpinx(난관)에서 유래.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-025','med-basic-ch01',25,'객관식','어원','하','고대 그리스의 ''의학의 아버지''로 불리며 많은 의학용어를 만들어낸 인물은?','{"choices": ["Bartolommeo Eustachio", "Hippocrates(히포크라테스)", "Eros", "Psyche"]}','"B"','히포크라테스는 그리스 의학의 아버지로, 그림 1-4의 흉상으로 표현된다.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-026','med-basic-ch01',26,'단답형','결합형 (인체 해부도)','중',replace('그림 1-3의 인체 해부도에서 다음 결합형이 나타내는 신체 부위를 한국어로 쓰시오.\n(1) Trache/o (2) Bronch/o (3) Angi/o (4) Ot/o (5) Ocul/o','\n',char(10)),'{}','{"1": "기관 (trachea)", "2": "기관지 (bronchus)", "3": "혈관 (vessel)", "4": "귀 (ear)", "5": "눈 (eye)"}',NULL,NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-027','med-basic-ch01',27,'단답형','용어 만들기','상','''신생아를 연구하는 학문''에 해당하는 의학용어를 만드시오. (힌트: neo- + nat/o + -logy)','{}','"neonatology"','neo-(새로운) + nat(출생) + o + -logy(학문) → 신생아학.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-028','med-basic-ch01',28,'용어분해','단어 분해','상','다음 용어를 단어 요소로 분리하고, 각 부분의 의미를 적으시오: electrocardiogram','{"parts": [{"role": "r", "value": "electr", "label_ko": "어근1", "meaning": "전기"}, {"role": "cv", "value": "o", "label_ko": "결합모음"}, {"role": "r", "value": "cardi", "label_ko": "어근2", "meaning": "심장"}, {"role": "cv", "value": "o", "label_ko": "결합모음"}, {"role": "s", "value": "-gram", "label_ko": "접미사", "meaning": "기록/이미지"}]}','"electr/o/cardi/o/gram"','전기로 측정한 심장의 기록 → 심전도(ECG). 어근이 2개이므로 어근 사이·어근-접미사 사이에 결합 모음 o가 두 번 들어간다.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-029','med-basic-ch01',29,'객관식','용어 의미','중','다음 중 ''aphasia''의 뜻으로 옳은 것은?','{"choices": ["혈액의 결핍", "말이 없음(실어증)", "신경의 염증", "심장의 통증"]}','"B"','a-(부재/없는) + -phasia(말, 언어) → 말이 없음(실어증). 접두사+접미사로만 이루어진 의학용어의 예.',NULL);
INSERT INTO "med_exam_items" ("id","chapter_id","no","type","topic","difficulty","question","body_json","answer_json","explanation","figure_id") VALUES('ei-ch01-030','med-basic-ch01',30,'매칭','어원 어근','상','표 1-1에 따라 어근과 의학용어 예시를 짝지으시오.','{"items": {"1": "lith (그리스어 lithos)", "2": "maxim (라틴어 maximus)", "3": "derm (그리스어 derma)", "4": "path (그리스어 pathos)"}, "options": {"a": "dermatitis (피부염)", "b": "cholelithiasis (담석증)", "c": "pathogen (질병을 일으키는 인자)", "d": "gluteus maximus (엉덩이의 가장 큰 근육)"}}','{"1": "b", "2": "d", "3": "a", "4": "c"}',NULL,NULL);
