INSERT INTO "vocab_print_jobs" ("id","academy_id","student_id","word_ids_json","grammar_ids_json","pdf_r2_key","created_by","created_at","status","started_at","submitted_at","auto_correct","auto_total","policy_id","has_writing","source") VALUES('vpj-d3e59cb7','acad-1','gstu-010e0bbf','["vw-8ccda782","vw-d29cc021","vw-18a10ddc","vw-939fbce2","vw-a311f989","vw-b79398ff","vw-c3bcc419","vw-906fbdef","vw-f0b99fae","vw-ceb3e124"]',NULL,NULL,'student:gstu-010e0bbf','2026-05-14 06:14:38','submitted','2026-05-14 06:14:38','2026-05-14T06:15:46.903Z',8,10,'vep-default-acad-1',0,'mywords');
