PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  role TEXT DEFAULT 'instructor',
  academy_id TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT 'active', subjects TEXT, last_login_at DATETIME, password_must_change INTEGER DEFAULT 0, password_reset_at DATETIME,
  FOREIGN KEY (academy_id) REFERENCES academies(id)
);
CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  refresh_token TEXT NOT NULL UNIQUE,
  expires_at DATETIME NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE academies (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  phone TEXT,
  address TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, default_class_id TEXT, slug TEXT, owner_id TEXT, plan TEXT DEFAULT 'free', max_students INTEGER DEFAULT 30, max_teachers INTEGER DEFAULT 3, is_active INTEGER DEFAULT 1, logo_url TEXT, expires_at DATETIME);
CREATE TABLE classes (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  name TEXT NOT NULL,
  grade TEXT,
  day_of_week INTEGER,
  start_time TEXT,
  end_time TEXT,
  instructor_id TEXT,
  capacity INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  FOREIGN KEY (instructor_id) REFERENCES users(id)
);
CREATE TABLE students (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  name TEXT NOT NULL,
  class_id TEXT,
  contact TEXT,
  guardian_contact TEXT,
  enrollment_date DATE,
  status TEXT DEFAULT 'active',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, grade TEXT, subjects TEXT DEFAULT '[]', school TEXT, pin_hash TEXT, pin_salt TEXT NOT NULL DEFAULT '', teacher_id TEXT,
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  FOREIGN KEY (class_id) REFERENCES classes(id)
);
CREATE TABLE attendance (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  class_id TEXT NOT NULL,
  date DATE NOT NULL,
  status TEXT DEFAULT 'present',
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (student_id) REFERENCES students(id),
  FOREIGN KEY (class_id) REFERENCES classes(id),
  UNIQUE(student_id, class_id, date)
);
CREATE TABLE reports (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  month TEXT NOT NULL,
  content TEXT,
  pdf_url TEXT,
  generated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  sent_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (student_id) REFERENCES students(id)
);
CREATE TABLE messages (
  id TEXT PRIMARY KEY,
  sender_id TEXT NOT NULL,
  recipient_id TEXT NOT NULL,
  content TEXT NOT NULL,
  is_read BOOLEAN DEFAULT FALSE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (sender_id) REFERENCES users(id),
  FOREIGN KEY (recipient_id) REFERENCES users(id)
);
CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  action TEXT NOT NULL,
  resource_type TEXT,
  resource_id TEXT,
  changes TEXT,
  ip_address TEXT,
  user_agent TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE report_send_configs (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  UNIQUE(academy_id)
);
CREATE TABLE IF NOT EXISTS "exams" (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  class_id TEXT,
  name TEXT NOT NULL,
  exam_month TEXT,
  date DATE NOT NULL,
  total_score REAL,
  is_active BOOLEAN DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME, exam_type TEXT NOT NULL DEFAULT 'monthly', term TEXT,
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  FOREIGN KEY (class_id) REFERENCES classes(id)
);
CREATE TABLE exam_settings (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  active_exam_month TEXT NOT NULL,
  updated_by TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  UNIQUE(academy_id)
);
CREATE TABLE student_teachers (student_id TEXT NOT NULL, teacher_id TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')), is_homeroom INTEGER NOT NULL DEFAULT 0, subjects TEXT NOT NULL DEFAULT '[]', PRIMARY KEY (student_id, teacher_id), FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY (teacher_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE report_sends (id TEXT PRIMARY KEY, academy_id TEXT NOT NULL, student_id TEXT NOT NULL, year_month TEXT NOT NULL, share_url TEXT NOT NULL, image_path TEXT NOT NULL, sent_by TEXT NOT NULL, sent_at TEXT NOT NULL, UNIQUE(academy_id, student_id, year_month));
CREATE TABLE class_students (id TEXT PRIMARY KEY, class_id TEXT NOT NULL, student_id TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, UNIQUE(class_id, student_id));
CREATE TABLE absences (id TEXT PRIMARY KEY, student_id TEXT NOT NULL, class_id TEXT NOT NULL, absence_date DATE NOT NULL, reason TEXT DEFAULT '', notified_by TEXT DEFAULT '', notified_at TEXT, status TEXT DEFAULT 'absent', recorded_by TEXT, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (class_id) REFERENCES classes(id), UNIQUE(student_id, class_id, absence_date));
CREATE TABLE makeups (id TEXT PRIMARY KEY, absence_id TEXT NOT NULL, scheduled_date DATE, completed_date DATE, status TEXT DEFAULT 'pending', notes TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), scheduled_start_time TEXT, scheduled_end_time TEXT, FOREIGN KEY (absence_id) REFERENCES absences(id) ON DELETE CASCADE, UNIQUE(absence_id));
CREATE TABLE notices (id TEXT PRIMARY KEY, academy_id TEXT NOT NULL, author_id TEXT NOT NULL, title TEXT NOT NULL, content TEXT DEFAULT '', category TEXT DEFAULT 'general', is_pinned INTEGER DEFAULT 0, due_date DATE, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (academy_id) REFERENCES academies(id), FOREIGN KEY (author_id) REFERENCES users(id));
CREATE TABLE notice_reads (id TEXT PRIMARY KEY, notice_id TEXT NOT NULL, user_id TEXT NOT NULL, read_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (notice_id) REFERENCES notices(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id), UNIQUE(notice_id, user_id));
CREATE TABLE action_items (id TEXT PRIMARY KEY, academy_id TEXT NOT NULL, notice_id TEXT, title TEXT NOT NULL, description TEXT DEFAULT '', assigned_to TEXT NOT NULL, assigned_by TEXT NOT NULL, due_date DATE, status TEXT DEFAULT 'pending', completed_at TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (academy_id) REFERENCES academies(id), FOREIGN KEY (notice_id) REFERENCES notices(id) ON DELETE SET NULL, FOREIGN KEY (assigned_to) REFERENCES users(id), FOREIGN KEY (assigned_by) REFERENCES users(id));
CREATE TABLE exam_review_settings (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  active_term TEXT NOT NULL,          -- '2026-1'
  active_exam_type TEXT NOT NULL,     -- 'midterm' | 'final'
  updated_by TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  UNIQUE(academy_id)
);
CREATE TABLE exam_review_sends (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  term TEXT NOT NULL,
  exam_type TEXT NOT NULL,
  share_url TEXT NOT NULL,
  image_path TEXT NOT NULL,
  sent_by TEXT NOT NULL,
  sent_at TEXT NOT NULL,
  UNIQUE(academy_id, student_id, term, exam_type)
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE enrollments (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  day TEXT NOT NULL,            -- '월'|'화'|'수'|'목'|'금'|'토'|'일'
  start_time TEXT NOT NULL,     -- 'HH:mm'
  end_time TEXT NOT NULL,       -- 'HH:mm'
  subject TEXT,                 -- '수학' 등, NULL 허용
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE realtime_sessions (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  teacher_id TEXT NOT NULL,         -- 체크인한 선생님 (본인 담당)
  academy_id TEXT NOT NULL,
  date TEXT NOT NULL,                -- 'YYYY-MM-DD' (검색 인덱스용)
  check_in_time TEXT NOT NULL,       -- ISO datetime
  check_out_time TEXT,               -- ISO datetime (체크아웃 전 NULL)
  status TEXT NOT NULL,              -- 'active'|'paused'|'completed'|'overtime'
  scheduled_minutes INTEGER NOT NULL DEFAULT 0,
  added_minutes INTEGER NOT NULL DEFAULT 0,
  scheduled_start_time TEXT,         -- 'HH:mm' (enrollment 에서 복사)
  scheduled_end_time TEXT,           -- 'HH:mm'
  pause_history TEXT NOT NULL DEFAULT '[]',  -- JSON
  subject TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')), makeup_id TEXT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (teacher_id) REFERENCES users(id),
  FOREIGN KEY (academy_id) REFERENCES academies(id)
);
CREATE TABLE attendance_records (
  id TEXT PRIMARY KEY,
  session_id TEXT,                    -- 원본 realtime_session 참조 (감사용)
  student_id TEXT NOT NULL,
  teacher_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  date TEXT NOT NULL,                  -- 'YYYY-MM-DD'
  check_in_time TEXT NOT NULL,
  check_out_time TEXT NOT NULL,
  scheduled_start_time TEXT,
  scheduled_end_time TEXT,
  scheduled_minutes INTEGER NOT NULL,
  net_minutes INTEGER NOT NULL,        -- 순수 수업시간 (총 - 정지)
  total_paused_minutes INTEGER NOT NULL DEFAULT 0,
  pause_count INTEGER NOT NULL DEFAULT 0,
  pause_history TEXT NOT NULL DEFAULT '[]',
  subject TEXT,
  was_late INTEGER NOT NULL DEFAULT 0,
  was_overtime INTEGER NOT NULL DEFAULT 0,
  note TEXT,
  created_at TEXT DEFAULT (datetime('now')), added_minutes INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (student_id) REFERENCES students(id),
  FOREIGN KEY (teacher_id) REFERENCES users(id),
  FOREIGN KEY (academy_id) REFERENCES academies(id)
);
CREATE TABLE invitations (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  code TEXT UNIQUE NOT NULL,
  role TEXT DEFAULT 'instructor',
  created_by TEXT NOT NULL,
  used_by TEXT,
  expires_at DATETIME NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE meetings (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '회의',
  audio_url TEXT,
  transcript TEXT,
  summary TEXT,
  key_decisions TEXT,        -- JSON array
  status TEXT NOT NULL DEFAULT 'recording',  -- recording | transcribing | summarizing | done | error
  error_message TEXT,
  duration_seconds INTEGER,
  participants TEXT,          -- JSON array of names
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (academy_id) REFERENCES academies(id),
  FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE meeting_actions (
  id TEXT PRIMARY KEY,
  meeting_id TEXT NOT NULL,
  title TEXT NOT NULL,
  assignee_name TEXT,
  due_date TEXT,
  status TEXT NOT NULL DEFAULT 'pending',  -- pending | done
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (meeting_id) REFERENCES meetings(id) ON DELETE CASCADE
);
CREATE TABLE proofs (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  title TEXT NOT NULL,
  grade TEXT NOT NULL,
  chapter TEXT,
  difficulty INTEGER DEFAULT 1,
  description TEXT,
  description_image TEXT,
  is_shared INTEGER DEFAULT 0,
  share_count INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME
, theorem_statement TEXT, subject TEXT, source_path TEXT);
CREATE TABLE proof_steps (
  id TEXT PRIMARY KEY,
  proof_id TEXT NOT NULL,
  step_order INTEGER NOT NULL,
  content TEXT NOT NULL,
  content_image TEXT,
  blanks_json TEXT,
  hint TEXT,
  FOREIGN KEY (proof_id) REFERENCES proofs(id) ON DELETE CASCADE
);
CREATE TABLE proof_shares (
  id TEXT PRIMARY KEY,
  original_proof_id TEXT NOT NULL,
  shared_by TEXT NOT NULL,
  copied_by TEXT,
  copied_academy_id TEXT,
  copied_proof_id TEXT,
  copied_at DATETIME,
  FOREIGN KEY (original_proof_id) REFERENCES proofs(id)
);
CREATE TABLE exam_periods (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  title TEXT NOT NULL,
  period_month TEXT NOT NULL,
  status TEXT DEFAULT 'preparing',
  created_by TEXT NOT NULL,
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME DEFAULT (datetime('now')),
  UNIQUE(academy_id, period_month)
);
CREATE TABLE exam_papers (
  id TEXT PRIMARY KEY,
  exam_period_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  title TEXT NOT NULL,
  grade_filter TEXT,
  is_custom INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT (datetime('now')), subject TEXT, duration_minutes INTEGER DEFAULT 50,
  FOREIGN KEY (exam_period_id) REFERENCES exam_periods(id) ON DELETE CASCADE
);
CREATE TABLE proof_givens (
  id TEXT PRIMARY KEY,
  proof_id TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'definition',
  label TEXT,
  content TEXT NOT NULL,
  order_idx INTEGER DEFAULT 0,
  FOREIGN KEY (proof_id) REFERENCES proofs(id) ON DELETE CASCADE
);
CREATE TABLE proof_phases (
  id TEXT PRIMARY KEY,
  proof_id TEXT NOT NULL,
  phase_no INTEGER NOT NULL,
  phase_type TEXT NOT NULL,
  prompt TEXT NOT NULL,
  model_answer TEXT,
  UNIQUE(proof_id, phase_no),
  FOREIGN KEY (proof_id) REFERENCES proofs(id) ON DELETE CASCADE
);
CREATE TABLE proof_phase_items (
  id TEXT PRIMARY KEY,
  phase_id TEXT NOT NULL,
  item_key TEXT NOT NULL,
  content TEXT NOT NULL,
  correct_answer TEXT,
  meta_json TEXT,
  order_idx INTEGER DEFAULT 0,
  FOREIGN KEY (phase_id) REFERENCES proof_phases(id) ON DELETE CASCADE
);
CREATE TABLE proof_figures (
  id TEXT PRIMARY KEY,
  proof_id TEXT NOT NULL,
  phase_id TEXT,
  svg_content TEXT NOT NULL,
  coords_json TEXT NOT NULL,
  verify_meta_json TEXT,
  verify_result_json TEXT,
  highlight_keys TEXT,
  alt_text TEXT NOT NULL,
  review_status TEXT DEFAULT 'pending',
  created_at DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (proof_id) REFERENCES proofs(id) ON DELETE CASCADE,
  FOREIGN KEY (phase_id) REFERENCES proof_phases(id) ON DELETE SET NULL
);
CREATE TABLE paper_handouts (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  title TEXT NOT NULL,
  exam_type TEXT NOT NULL,         -- 'midterm' | 'final' | 'performance'
  subject TEXT,
  school TEXT,
  grade TEXT,
  exam_year INTEGER,
  semester INTEGER,                -- 1 | 2
  file_key TEXT,
  file_name TEXT,
  file_size INTEGER,
  content_type TEXT,
  memo TEXT DEFAULT '',
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE paper_handout_distributions (
  id TEXT PRIMARY KEY,
  paper_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'auto',
  distributed_at TEXT NOT NULL DEFAULT (datetime('now')),
  viewed_at TEXT,
  UNIQUE(paper_id, student_id),
  FOREIGN KEY (paper_id) REFERENCES paper_handouts(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "exam_assignments" (
  id TEXT PRIMARY KEY,
  exam_period_id TEXT NOT NULL,
  exam_paper_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  created_check INTEGER DEFAULT 0,
  printed INTEGER DEFAULT 0,
  reviewed INTEGER DEFAULT 0,
  drive_link TEXT,
  score REAL,
  memo TEXT,
  created_at DATETIME DEFAULT (datetime('now')), exam_date TEXT, exam_status TEXT DEFAULT 'scheduled', absence_reason TEXT, rescheduled_date TEXT, rescheduled_memo TEXT, adhoc_session_id TEXT, is_repeatable INTEGER NOT NULL DEFAULT 0,
  UNIQUE(exam_period_id, student_id),
  FOREIGN KEY (exam_period_id) REFERENCES exam_periods(id) ON DELETE CASCADE,
  FOREIGN KEY (exam_paper_id) REFERENCES exam_papers(id),
  FOREIGN KEY (student_id) REFERENCES students(id)
);
CREATE TABLE adhoc_sessions (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  teacher_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  date TEXT NOT NULL,              -- 'YYYY-MM-DD'
  start_time TEXT NOT NULL,        -- 'HH:mm'
  end_time TEXT NOT NULL,          -- 'HH:mm'
  subject TEXT,
  reason TEXT,                     -- '시간표변경','보충수업','시험대비','대타','기타'
  status TEXT DEFAULT 'scheduled', -- 'scheduled'|'completed'|'cancelled'
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (teacher_id) REFERENCES users(id),
  FOREIGN KEY (academy_id) REFERENCES academies(id)
);
CREATE TABLE IF NOT EXISTS "grades" (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  exam_id TEXT NOT NULL,
  score REAL,
  comments TEXT,
  graded_at DATETIME,
  graded_by TEXT,
  created_at DATETIME DEFAULT (datetime('now')),
  year_month TEXT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (exam_id) REFERENCES exams(id) ON DELETE CASCADE
);
CREATE TABLE vocab_textbooks (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  school TEXT,
  grade TEXT,
  semester TEXT,
  title TEXT NOT NULL,
  created_by TEXT,
  created_at DATETIME DEFAULT (datetime('now'))
);
CREATE TABLE vocab_textbook_words (
  id TEXT PRIMARY KEY,
  textbook_id TEXT NOT NULL,
  unit TEXT,
  english TEXT NOT NULL,
  korean TEXT NOT NULL,
  sentence TEXT,
  FOREIGN KEY (textbook_id) REFERENCES vocab_textbooks(id) ON DELETE CASCADE
);
CREATE TABLE vocab_grade_results (
  id TEXT PRIMARY KEY,
  print_job_id TEXT NOT NULL,
  word_id TEXT NOT NULL,
  correct INTEGER NOT NULL,                 -- 0|1
  box_before INTEGER,
  box_after INTEGER,
  graded_at DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (print_job_id) REFERENCES vocab_print_jobs(id) ON DELETE CASCADE,
  FOREIGN KEY (word_id) REFERENCES vocab_words(id) ON DELETE CASCADE
);
CREATE TABLE exam_attempts (
  id TEXT PRIMARY KEY,
  exam_assignment_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  realtime_session_id TEXT,                    -- 어떤 수업 입실 중에 친 시험인지 (회고 분석용)

  duration_minutes INTEGER NOT NULL,           -- 이 시험의 총 제한시간 (분)

  status TEXT NOT NULL DEFAULT 'ready',
    -- ready    : 배정만 됨, 미시작
    -- running  : 진행 중
    -- paused   : 일시정지
    -- submitted: 학생 제출
    -- expired  : 시간 종료 (자동)
    -- voided   : 무효 처리

  started_at TEXT,                             -- ISO8601 (running/이후)
  ended_at TEXT,                               -- 종료 시각 (submitted/expired/voided)

  pause_history TEXT DEFAULT '[]',             -- JSON: [{pausedAt, resumedAt, reason, byUserId}]
  total_paused_seconds INTEGER DEFAULT 0,     -- 누적 정지 시간

  proctor_user_id TEXT,                        -- 시작 처리한 감독 교사 (audit)
  submit_note TEXT,                            -- 제출 시 비고 (옵션)

  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME DEFAULT (datetime('now')), auto_score   REAL, auto_correct INTEGER, auto_total   INTEGER,

  FOREIGN KEY (exam_assignment_id) REFERENCES exam_assignments(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id),
  FOREIGN KEY (academy_id) REFERENCES academies(id)
);
CREATE TABLE assignments (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  created_by TEXT NOT NULL,                    -- users.id (teacher/admin)
  title TEXT NOT NULL,
  instructions TEXT,
  kind TEXT NOT NULL DEFAULT 'general',        -- 'perf_eval' | 'exam_paper' | 'general'
  due_at DATETIME,
  attached_file_key TEXT,                      -- R2 key (선생님 첨부; 양식·시험지 등)
  attached_file_name TEXT,
  status TEXT NOT NULL DEFAULT 'published',    -- 'published' | 'closed'
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME DEFAULT (datetime('now'))
);
CREATE TABLE assignment_submissions (
  id TEXT PRIMARY KEY,
  target_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  note TEXT,
  files TEXT NOT NULL DEFAULT '[]',            -- JSON: [{key, name, size, mime}]
  submitted_at DATETIME DEFAULT (datetime('now'))
);
CREATE TABLE assignment_responses (
  id TEXT PRIMARY KEY,
  target_id TEXT NOT NULL,
  submission_id TEXT,                          -- nullable: 특정 제출 미연결도 가능
  teacher_id TEXT NOT NULL,                    -- users.id
  academy_id TEXT NOT NULL,
  comment TEXT,
  file_key TEXT,                               -- R2 key (첨삭본 PDF 등; nullable)
  file_name TEXT,
  action TEXT NOT NULL DEFAULT 'accept',       -- 'accept'|'needs_resubmit'
  created_at DATETIME DEFAULT (datetime('now'))
);
CREATE TABLE student_play_state (
  student_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  state_json TEXT NOT NULL DEFAULT '{}',
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (student_id, academy_id)
);
CREATE TABLE consultations (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  author_id TEXT NOT NULL,          -- 작성 선생님
  channel TEXT NOT NULL,            -- phone | sms | kakao | in_person | other
  category TEXT NOT NULL DEFAULT 'monthly', -- monthly | pre_exam | post_exam | ad_hoc
  consulted_at TEXT NOT NULL,       -- 실제 상담 일시 (ISO)
  subjects TEXT,                    -- JSON array, 다과목 상담 시 과목 태그
  summary TEXT NOT NULL,            -- 상담 요약 (공유 대상 본문)
  parent_sentiment TEXT,            -- positive | neutral | concerned | null
  follow_up TEXT,                   -- 다음 액션/후속 상담 메모
  follow_up_due TEXT,               -- YYYY-MM-DD, 후속 일정
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (academy_id) REFERENCES academies(id) ON DELETE CASCADE
);
CREATE TABLE student_external_schedules (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  author_id TEXT NOT NULL,
  kind TEXT NOT NULL,               -- other_subject | other_academy | exam | event
  title TEXT NOT NULL,              -- 예: "수학 1:1 (화목 7시)", "중간고사 수학"
  starts_at TEXT,                   -- ISO 또는 YYYY-MM-DD (시험/이벤트용)
  ends_at TEXT,
  recurrence TEXT,                  -- weekly | once | null (자유 표기)
  location TEXT,                    -- 타학원명 등
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (academy_id) REFERENCES academies(id) ON DELETE CASCADE
);
CREATE TABLE student_teacher_notes (
  id              TEXT PRIMARY KEY,
  academy_id      TEXT NOT NULL,
  student_id      TEXT NOT NULL,
  author_id       TEXT NOT NULL,        -- 작성한 교과 선생님 (users.id)
  subject         TEXT NOT NULL,        -- '수학' | '영어' | ... (학원 subjects 어휘)
  category        TEXT NOT NULL,        -- attitude | understanding | homework | exam | etc
  sentiment       TEXT NOT NULL,        -- positive | neutral | concern
  tags            TEXT,                 -- JSON array (예: ["보강필요","집중부족"])
  content         TEXT NOT NULL,        -- 본문 (1~3줄 권장, 최대 1000자)
  source          TEXT NOT NULL DEFAULT 'manual', -- manual | post_class | post_exam | post_assignment
  source_ref_id   TEXT,                 -- exam_id / assignment_id 등 (선택)
  visibility      TEXT NOT NULL DEFAULT 'staff',  -- staff | homeroom_only | parent_share
  period_tag      TEXT NOT NULL,        -- 'YYYY-WW' 또는 'YYYY-MM' (요약 단위 인덱스)
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (academy_id) REFERENCES academies(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id)  REFERENCES users(id)    ON DELETE RESTRICT
);
CREATE TABLE live_sessions (
  id              TEXT PRIMARY KEY,
  academy_id      TEXT NOT NULL,
  teacher_id      TEXT NOT NULL,
  student_id      TEXT NOT NULL,
  subject         TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'active', -- active | ended | abandoned
  started_at      TEXT NOT NULL DEFAULT (datetime('now')),
  ended_at        TEXT,
  duration_sec    INTEGER,
  problem_text    TEXT,
  problem_r2_key  TEXT,
  teacher_solution_text   TEXT,
  teacher_solution_r2_key TEXT,
  student_answer_text     TEXT,
  student_answer_r2_key   TEXT,
  note_id         TEXT,
  FOREIGN KEY (academy_id) REFERENCES academies(id) ON DELETE CASCADE,
  FOREIGN KEY (teacher_id) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE exam_questions (
  id TEXT PRIMARY KEY,
  exam_paper_id TEXT NOT NULL,
  question_no INTEGER NOT NULL,
  prompt TEXT NOT NULL,
  choices TEXT NOT NULL,             -- JSON: ["a","b","c","d","e"]
  correct_choice INTEGER NOT NULL,   -- 1..5
  points REAL DEFAULT 1,
  created_at DATETIME DEFAULT (datetime('now')), category TEXT,
  UNIQUE (exam_paper_id, question_no),
  FOREIGN KEY (exam_paper_id) REFERENCES exam_papers(id) ON DELETE CASCADE
);
CREATE TABLE exam_answers (
  attempt_id TEXT NOT NULL,
  question_no INTEGER NOT NULL,
  selected_choice INTEGER,
  saved_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (attempt_id, question_no),
  FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE
);
CREATE TABLE vocab_print_answers (
  print_job_id   TEXT NOT NULL,
  word_id        TEXT NOT NULL,
  selected_index INTEGER,         -- 0..3 or NULL
  correct_index  INTEGER NOT NULL,
  choices_json   TEXT NOT NULL,   -- JSON: ["...","...","...","..."]
  saved_at       TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (print_job_id, word_id),
  FOREIGN KEY (print_job_id) REFERENCES vocab_print_jobs(id) ON DELETE CASCADE,
  FOREIGN KEY (word_id) REFERENCES vocab_words(id) ON DELETE CASCADE
);
CREATE TABLE vocab_exam_policy (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  scope TEXT NOT NULL,                -- 'academy' | 'teacher' | 'student'
  scope_id TEXT,                      -- teacher_id / student_id (academy면 NULL)

  -- 풀 구성
  vocab_count INTEGER NOT NULL DEFAULT 10,
  context_count INTEGER NOT NULL DEFAULT 0,    -- 어휘 맥락 4지선다 (Phase 2)
  grammar_count INTEGER NOT NULL DEFAULT 0,    -- 문법 4지선다 (Phase 2)
  writing_enabled INTEGER NOT NULL DEFAULT 0,  -- 영작 포함 여부
  writing_type TEXT,                  -- sentence_completion | word_arrangement | summary_writing | free_writing | NULL=학생선택

  -- 출제 규칙
  box_filter TEXT NOT NULL DEFAULT '1,2,3,4',  -- CSV: 어떤 box에서 뽑을지 (5 제외 권장)
  source TEXT NOT NULL DEFAULT 'student_pool', -- student_pool | textbook | mixed
  textbook_id TEXT,                            -- source가 textbook일 때

  -- 응시 제약
  time_limit_sec INTEGER NOT NULL DEFAULT 600, -- 0 = 무제한
  cooldown_min INTEGER NOT NULL DEFAULT 60,    -- 마지막 응시 후 N분 잠금
  daily_limit INTEGER NOT NULL DEFAULT 3,      -- 0 = 무제한
  active_from TEXT,                            -- 'HH:MM' (NULL=24시간)
  active_to TEXT,                              -- 'HH:MM'
  word_cooldown_min INTEGER NOT NULL DEFAULT 30, -- 같은 단어 재출제 금지 분

  -- 영작 채점
  ai_grading INTEGER NOT NULL DEFAULT 1,

  enabled INTEGER NOT NULL DEFAULT 1,
  created_by TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT, textbook_filters_json TEXT, mix_ratio_common INTEGER NOT NULL DEFAULT 50,

  UNIQUE (academy_id, scope, scope_id)
);
CREATE TABLE vocab_writing_responses (
  exam_id TEXT PRIMARY KEY,
  problem_type TEXT NOT NULL,                  -- sentence_completion | word_arrangement | summary_writing | free_writing
  problem TEXT NOT NULL,                       -- JSON
  target_words TEXT NOT NULL,                  -- JSON: [{id,english,korean}]
  student_answer TEXT,
  grade TEXT,                                  -- JSON: Gemini 채점 결과
  graded_at TEXT,
  FOREIGN KEY (exam_id) REFERENCES vocab_print_jobs(id) ON DELETE CASCADE
);
CREATE TABLE student_lesson_items (
  id              TEXT PRIMARY KEY,
  academy_id      TEXT NOT NULL,
  student_id      TEXT NOT NULL,

  -- 진도 좌표
  textbook        TEXT,
  unit_name       TEXT,
  kind            TEXT NOT NULL DEFAULT 'unit',  -- 'unit' | 'type' | 'free'
  order_idx       INTEGER NOT NULL DEFAULT 0,

  -- 이해도/상태
  understanding   INTEGER,                       -- 0..100, NULL=미평가
  status          TEXT NOT NULL DEFAULT 'todo',  -- 'todo' | 'in_progress' | 'done'
  note            TEXT,

  -- 자료 메타
  title           TEXT,
  purpose         TEXT,
  topic           TEXT,
  description     TEXT,
  tags            TEXT,                          -- JSON array
  coverage_category TEXT,

  -- 학부모 노출 (scope=student 1종만 사용 → 불리언)
  visible_to_parent     INTEGER NOT NULL DEFAULT 0,
  parent_can_download   INTEGER NOT NULL DEFAULT 1,

  created_by      TEXT NOT NULL,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  updated_by      TEXT,
  updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
  archived_at     TEXT, curriculum_item_id TEXT
  REFERENCES curriculum_items(id) ON DELETE SET NULL, source TEXT NOT NULL DEFAULT 'manual',

  FOREIGN KEY (academy_id) REFERENCES academies(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id)  ON DELETE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users(id)     ON DELETE RESTRICT
);
CREATE TABLE lesson_item_files (
  id              TEXT PRIMARY KEY,
  lesson_item_id  TEXT NOT NULL,
  r2_key          TEXT NOT NULL,
  file_name       TEXT NOT NULL,
  file_role       TEXT NOT NULL DEFAULT 'main',  -- 'main' | 'answer' | 'solution' | 'extra'
  mime_type       TEXT,
  size_bytes      INTEGER NOT NULL DEFAULT 0,
  version         INTEGER NOT NULL DEFAULT 1,
  uploaded_by     TEXT NOT NULL,
  uploaded_at     TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (lesson_item_id) REFERENCES student_lesson_items(id) ON DELETE CASCADE,
  FOREIGN KEY (uploaded_by)    REFERENCES users(id) ON DELETE RESTRICT
);
CREATE TABLE curricula (
  id              TEXT PRIMARY KEY,
  academy_id      TEXT NOT NULL,
  term            TEXT NOT NULL,        -- '2026-1' | '2026-여름' | '2026-2'
  grade           TEXT NOT NULL,        -- '중1' | '중2' | '고1' ...
  subject         TEXT NOT NULL,        -- '수학' | '영어' ...
  title           TEXT NOT NULL,        -- '2026-1 중1 수학'
  description     TEXT,
  created_by      TEXT NOT NULL,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
  archived_at     TEXT,
  FOREIGN KEY (academy_id) REFERENCES academies(id) ON DELETE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE TABLE curriculum_items (
  id              TEXT PRIMARY KEY,
  curriculum_id   TEXT NOT NULL,
  textbook        TEXT,
  unit_name       TEXT NOT NULL,
  kind            TEXT NOT NULL DEFAULT 'type',  -- 'unit' | 'type'
  order_idx       INTEGER NOT NULL DEFAULT 0,
  description     TEXT,
  default_purpose TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (curriculum_id) REFERENCES curricula(id) ON DELETE CASCADE
);
CREATE TABLE vocab_catalogs (
  id          TEXT PRIMARY KEY,                  -- 'csat-megastudy-2025'
  title       TEXT NOT NULL,
  source      TEXT NOT NULL,                     -- 'megastudy-2025-pdf'
  license     TEXT,
  word_count  INTEGER NOT NULL DEFAULT 0,
  created_at  DATETIME DEFAULT (datetime('now'))
, kind TEXT NOT NULL DEFAULT 'vocab');
CREATE TABLE vocab_catalog_words (
  id          TEXT PRIMARY KEY,                  -- 'cw-csat-0001'
  catalog_id  TEXT NOT NULL,
  english     TEXT NOT NULL,
  korean      TEXT NOT NULL,
  pos         TEXT,                              -- noun|verb|adj|adv|prep|conj
  rank        INTEGER NOT NULL,                  -- 빈도 순위
  tier        INTEGER NOT NULL,                  -- 1|2|3
  example     TEXT,
  FOREIGN KEY (catalog_id) REFERENCES vocab_catalogs(id) ON DELETE CASCADE
);
CREATE TABLE student_vocab_catalogs (
  student_id  TEXT NOT NULL,
  catalog_id  TEXT NOT NULL,
  assigned_at DATETIME DEFAULT (datetime('now')),
  PRIMARY KEY (student_id, catalog_id),
  FOREIGN KEY (catalog_id) REFERENCES vocab_catalogs(id) ON DELETE CASCADE
);
CREATE TABLE med_books (
  id           TEXT PRIMARY KEY,
  title        TEXT NOT NULL,
  publisher    TEXT,
  edition      TEXT,
  field        TEXT,                        -- '간호'|'보건'|'의예'
  total_pages  INTEGER,
  created_at   DATETIME DEFAULT (datetime('now'))
);
CREATE TABLE med_chapters (
  id            TEXT PRIMARY KEY,
  book_id       TEXT NOT NULL,
  chapter_no    INTEGER NOT NULL,
  title         TEXT NOT NULL,
  page_start    INTEGER,
  page_end      INTEGER,
  objectives    TEXT,
  created_at    DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (book_id) REFERENCES med_books(id) ON DELETE CASCADE
);
CREATE TABLE med_word_parts (
  id           TEXT PRIMARY KEY,
  chapter_id   TEXT NOT NULL,
  role         TEXT NOT NULL,               -- 'p'|'r'|'cv'|'s'
  value        TEXT NOT NULL,               -- 'cardi/o' | 'anti-' | '-itis'
  meaning_ko   TEXT NOT NULL,
  meaning_en   TEXT,
  origin       TEXT,                        -- '그리스어'|'라틴어'
  origin_word  TEXT,                        -- 'lithos'
  notes        TEXT,
  FOREIGN KEY (chapter_id) REFERENCES med_chapters(id) ON DELETE CASCADE
);
CREATE TABLE med_terms (
  id              TEXT PRIMARY KEY,
  chapter_id      TEXT NOT NULL,
  term            TEXT NOT NULL,
  pronunciation   TEXT,
  meaning_ko      TEXT NOT NULL,
  meaning_long    TEXT,
  category        TEXT,                     -- '해부'|'증상'|'질환'|'시술'|'약어'
  is_constructed  INTEGER NOT NULL DEFAULT 1, -- 0=비조합어, 1=조합어
  plural_form     TEXT,
  plural_rule     TEXT,                     -- 'a→ae'|'is→es'|'itis→itides'|'on/um→a'
  FOREIGN KEY (chapter_id) REFERENCES med_chapters(id) ON DELETE CASCADE
);
CREATE TABLE med_term_parts (
  id          TEXT PRIMARY KEY,
  term_id     TEXT NOT NULL,
  part_id     TEXT NOT NULL,
  position    INTEGER NOT NULL,
  FOREIGN KEY (term_id) REFERENCES med_terms(id) ON DELETE CASCADE,
  FOREIGN KEY (part_id) REFERENCES med_word_parts(id) ON DELETE RESTRICT
);
CREATE TABLE med_figures (
  id           TEXT PRIMARY KEY,
  chapter_id   TEXT NOT NULL,
  label        TEXT NOT NULL,                -- '그림 1-3'
  caption      TEXT,
  fig_type     TEXT NOT NULL,                -- 'anatomy'|'diagram'|'etymology'|'illustration'
  r2_key       TEXT NOT NULL,                -- medterm/{academy_id}/figs/{figure_id}.{ext}
  width        INTEGER,
  height       INTEGER,
  created_at   DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (chapter_id) REFERENCES med_chapters(id) ON DELETE CASCADE
);
CREATE TABLE med_figure_labels (
  id           TEXT PRIMARY KEY,
  figure_id    TEXT NOT NULL,
  part_id      TEXT,                        -- 결합형 part 와 연결
  x_ratio      REAL NOT NULL,               -- 0.0~1.0
  y_ratio      REAL NOT NULL,
  text         TEXT NOT NULL,
  FOREIGN KEY (figure_id) REFERENCES med_figures(id) ON DELETE CASCADE,
  FOREIGN KEY (part_id) REFERENCES med_word_parts(id) ON DELETE SET NULL
);
CREATE TABLE med_exam_items (
  id            TEXT PRIMARY KEY,
  chapter_id    TEXT NOT NULL,
  no            INTEGER NOT NULL,
  type          TEXT NOT NULL,              -- '객관식'|'단답형'|'매칭'|'빈칸'|'용어분해'|'OX'
  topic         TEXT,
  difficulty    TEXT NOT NULL,              -- '하'|'중'|'상'
  question      TEXT NOT NULL,
  body_json     TEXT NOT NULL,              -- choices/items/options/parts 페이로드
  answer_json   TEXT NOT NULL,
  explanation   TEXT,
  figure_id     TEXT,
  FOREIGN KEY (chapter_id) REFERENCES med_chapters(id) ON DELETE CASCADE,
  FOREIGN KEY (figure_id) REFERENCES med_figures(id) ON DELETE SET NULL
);
CREATE TABLE med_exam_responses (
  id            TEXT PRIMARY KEY,
  attempt_id    TEXT NOT NULL,
  item_id       TEXT NOT NULL,
  response_json TEXT,
  correct       INTEGER,                         -- 0|1|NULL
  graded_at     DATETIME,
  FOREIGN KEY (attempt_id) REFERENCES med_exam_attempts(id) ON DELETE CASCADE,
  FOREIGN KEY (item_id) REFERENCES med_exam_items(id) ON DELETE CASCADE
);
CREATE TABLE student_signup_requests (
  id              TEXT PRIMARY KEY,
  academy_id      TEXT NOT NULL,
  name            TEXT NOT NULL,
  grade           TEXT,
  pin_hash        TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'pending',  -- 'pending' | 'rejected'
  memo            TEXT,                              -- 학생 자유 입력 (담당 교사명 등)
  submitted_at    DATETIME DEFAULT (datetime('now')),
  reviewed_at     DATETIME,
  reviewed_by     TEXT,                              -- 승인/거절한 교사 id
  reject_reason   TEXT, requested_teacher_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  UNIQUE(academy_id, name)
);
CREATE TABLE notifications (
  id                  TEXT PRIMARY KEY,
  academy_id          TEXT NOT NULL,
  recipient_user_id   TEXT REFERENCES users(id) ON DELETE CASCADE,
  recipient_role      TEXT,
  type                TEXT NOT NULL,
  title               TEXT NOT NULL,
  body                TEXT,
  link                TEXT,
  payload             TEXT,
  is_read             INTEGER NOT NULL DEFAULT 0,
  read_at             DATETIME,
  created_at          DATETIME NOT NULL DEFAULT (datetime('now')),
  expires_at          DATETIME
);
CREATE TABLE vocab_print_job_items (
  id              TEXT PRIMARY KEY,
  print_job_id    TEXT NOT NULL,
  academy_id      TEXT NOT NULL,           -- 격리용 redundant
  item_index      INTEGER NOT NULL,        -- 0..N-1 표시 순서

  -- pool 식별
  source          TEXT NOT NULL,           -- 'student' | 'textbook'
  source_word_id  TEXT NOT NULL,           -- vocab_words.id  OR  vocab_textbook_words.id

  -- 출제 시점 snapshot
  english         TEXT NOT NULL,
  korean          TEXT NOT NULL,
  unit_label      TEXT,                    -- textbook 일 때 "Unit 03 외모"
  textbook_title  TEXT,                    -- textbook 일 때 "어휘끝 고교기본"

  -- 4지선다
  choices_json    TEXT NOT NULL,           -- JSON 배열 ["A","B","C","D"]
  correct_index   INTEGER NOT NULL,        -- 0..3

  -- 응답·채점
  selected_index  INTEGER,                 -- 학생 선택, 미응답=NULL
  is_correct      INTEGER,                 -- 0|1, 미채점=NULL
  graded_at       TEXT,

  created_at      TEXT DEFAULT (datetime('now')),

  FOREIGN KEY (print_job_id) REFERENCES vocab_print_jobs(id) ON DELETE CASCADE
);
CREATE TABLE askai_conversations (
  id              TEXT PRIMARY KEY,          -- UUID v4
  student_id      TEXT NOT NULL,
  unit_id         TEXT,                       -- "확통 III-1 표본분포"
  message         TEXT NOT NULL,
  response_json   TEXT NOT NULL,              -- AskAIResponseSchema JSON
  confidence      TEXT NOT NULL CHECK (confidence IN ('high', 'medium', 'low')),
  needs_teacher   INTEGER NOT NULL DEFAULT 0, -- bool
  used_tokens     INTEGER,
  duration_ms     INTEGER,
  attached_photos TEXT,                       -- JSON array of R2 keys
  started_at      TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE askai_decisions (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  conversation_id TEXT NOT NULL,
  teacher_id      TEXT NOT NULL,
  decision        TEXT NOT NULL CHECK (decision IN ('ok', 'comment', 'ai_wrong')),
  comment         TEXT,
  applied_at      TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (conversation_id) REFERENCES askai_conversations(id) ON DELETE CASCADE
);
CREATE TABLE askai_quota (
  student_id      TEXT NOT NULL,
  date            TEXT NOT NULL,              -- YYYY-MM-DD (Asia/Seoul)
  questions_used  INTEGER NOT NULL DEFAULT 0,
  photos_used     INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (student_id, date)
);
CREATE TABLE askai_drill_cards (
  id              TEXT PRIMARY KEY,
  student_id      TEXT NOT NULL,
  source          TEXT NOT NULL CHECK (source IN (
    'askai_failed_checkpoint', 'exam_wrong', 'homework_deduction', 'unit_xmark'
  )),
  source_ref      TEXT NOT NULL,              -- conversation_id / exam_id / etc.
  unit            TEXT NOT NULL,
  problem_md      TEXT NOT NULL,
  answer_md       TEXT NOT NULL,
  context_note    TEXT,
  ai_cite         TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (student_id, source, source_ref)     -- dedup
);
CREATE TABLE askai_sm2_state (
  card_id         TEXT PRIMARY KEY,
  ease            REAL NOT NULL DEFAULT 2.5,
  interval_days   INTEGER NOT NULL DEFAULT 1,
  due_date        TEXT NOT NULL,              -- YYYY-MM-DD
  reps            INTEGER NOT NULL DEFAULT 0,
  lapses          INTEGER NOT NULL DEFAULT 0,
  updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (card_id) REFERENCES askai_drill_cards(id) ON DELETE CASCADE
);
CREATE TABLE askai_notifications (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id      TEXT NOT NULL,
  kind            TEXT NOT NULL CHECK (kind IN ('comment', 'ai_wrong')),
  conversation_id TEXT,
  payload_json    TEXT NOT NULL,
  read_at         TEXT,                       -- 학생이 확인한 시간
  sent_at         TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (conversation_id) REFERENCES askai_conversations(id) ON DELETE SET NULL
);
CREATE TABLE askai_photos (
  r2_key          TEXT PRIMARY KEY,
  student_id      TEXT NOT NULL,
  conversation_id TEXT,
  size_bytes      INTEGER NOT NULL,
  mime            TEXT NOT NULL,
  uploaded_at     TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at      TEXT NOT NULL,              -- YYYY-MM-DD (uploaded + 7d)
  FOREIGN KEY (conversation_id) REFERENCES askai_conversations(id) ON DELETE SET NULL
);
CREATE TABLE calendar_events (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  owner_type TEXT NOT NULL CHECK (owner_type IN ('academy','student')),
  owner_id TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('performance','school_exam','external_exam','academy','personal')),
  title TEXT NOT NULL,
  memo TEXT,
  link TEXT,
  start_date TEXT NOT NULL,        -- 'YYYY-MM-DD'
  end_date TEXT,                   -- nullable. NULL이면 단일일 이벤트
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  deleted_at INTEGER               -- soft delete
);
CREATE TABLE calendar_event_acks (
  event_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  read_at INTEGER NOT NULL,
  completed_at INTEGER,            -- NULL=미완료, 값=완료
  PRIMARY KEY (event_id, student_id),
  FOREIGN KEY (event_id) REFERENCES calendar_events(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "vocab_words" (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  english TEXT NOT NULL,
  korean TEXT NOT NULL,
  box INTEGER NOT NULL DEFAULT 1,
  blank_type TEXT NOT NULL DEFAULT 'korean',
  status TEXT NOT NULL DEFAULT 'approved',
  added_by TEXT NOT NULL DEFAULT 'teacher',
  review_count INTEGER NOT NULL DEFAULT 0,
  wrong_count INTEGER NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME,
  pos TEXT,
  example TEXT,
  last_quizzed_at TEXT,
  category TEXT,
  origin_catalog_word_id TEXT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "proof_results" (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  proof_id TEXT NOT NULL,
  session_id TEXT,
  mode TEXT NOT NULL,
  score INTEGER,
  time_spent INTEGER,
  detail_json TEXT,
  box INTEGER DEFAULT 1,
  attempted_at DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (proof_id) REFERENCES proofs(id) ON DELETE CASCADE
  -- session_id FK는 gacha_sessions가 Phase 5에서 DROP되므로 FK 제거
);
CREATE TABLE IF NOT EXISTS "proof_assignments" (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  proof_id TEXT NOT NULL,
  assigned_by TEXT NOT NULL,
  assigned_at DATETIME DEFAULT (datetime('now')),
  UNIQUE(student_id, proof_id),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (proof_id) REFERENCES proofs(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "proof_phase_results" (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL,
  proof_id TEXT NOT NULL,
  phase_no INTEGER NOT NULL,
  session_id TEXT,
  submitted_json TEXT NOT NULL,
  verify_status TEXT,
  score INTEGER,
  issues_json TEXT,
  time_spent INTEGER,
  attempted_at DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (proof_id) REFERENCES proofs(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "med_student_chapters" (
  id           TEXT PRIMARY KEY,
  academy_id   TEXT NOT NULL,
  student_id   TEXT NOT NULL,
  chapter_id   TEXT NOT NULL,
  modes_json   TEXT NOT NULL DEFAULT '["meaning"]',
  status       TEXT NOT NULL DEFAULT 'active',
  assigned_by  TEXT,
  assigned_at  DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (chapter_id) REFERENCES med_chapters(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "med_student_terms" (
  id              TEXT PRIMARY KEY,
  academy_id      TEXT NOT NULL,
  student_id      TEXT NOT NULL,
  term_id         TEXT NOT NULL,
  study_mode      TEXT NOT NULL DEFAULT 'meaning',
  box             INTEGER NOT NULL DEFAULT 1,
  review_count    INTEGER NOT NULL DEFAULT 0,
  wrong_count     INTEGER NOT NULL DEFAULT 0,
  last_reviewed   DATETIME,
  next_review     DATETIME DEFAULT (datetime('now')),
  created_at      DATETIME DEFAULT (datetime('now')),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (term_id) REFERENCES med_terms(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "med_exam_attempts" (
  id            TEXT PRIMARY KEY,
  academy_id    TEXT NOT NULL,
  student_id    TEXT NOT NULL,
  chapter_id    TEXT NOT NULL,
  item_ids_json TEXT NOT NULL,
  pdf_r2_key    TEXT,
  status        TEXT NOT NULL DEFAULT 'created',
  score         INTEGER,
  total         INTEGER,
  correct_cnt   INTEGER,
  created_at    DATETIME DEFAULT (datetime('now')),
  submitted_at  DATETIME,
  graded_at     DATETIME,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (chapter_id) REFERENCES med_chapters(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "assignment_targets" (
  id TEXT PRIMARY KEY,
  assignment_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  academy_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'assigned',
  assigned_at DATETIME DEFAULT (datetime('now')),
  last_submitted_at DATETIME,
  last_reviewed_at DATETIME,
  UNIQUE(assignment_id, student_id),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "vocab_grammar_qa" (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  student_id TEXT,
  question TEXT NOT NULL,
  answer TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  answered_by TEXT,
  include_in_print INTEGER NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT (datetime('now')),
  answered_at DATETIME,
  student_name TEXT,
  grade INTEGER,
  exam_problem TEXT,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS "vocab_print_jobs" (
  id TEXT PRIMARY KEY,
  academy_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  word_ids_json TEXT NOT NULL,
  grammar_ids_json TEXT,
  pdf_r2_key TEXT,
  created_by TEXT,
  created_at DATETIME DEFAULT (datetime('now')),
  status TEXT DEFAULT 'pending',
  started_at TEXT,
  submitted_at TEXT,
  auto_correct INTEGER,
  auto_total INTEGER,
  policy_id TEXT,
  has_writing INTEGER NOT NULL DEFAULT 0,
  source TEXT NOT NULL DEFAULT 'mywords',
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
